1	"use client";
2	
3	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
7	import BrandKitPanel from "@/components/brand/BrandKitPanel";
8	import BuildingOverlay from "./BuildingOverlay";
9	import BuildRating from "./BuildRating";
10	import BuildInterrupted, { type Interruption } from "./BuildInterrupted";
11	import CommandPalette, { type CommandGroup } from "./CommandPalette";
12	import CostEstimate, { type CreditRange } from "./CostEstimate";
13	import PreviewFrame, { DEVICES, type DeviceId } from "./PreviewFrame";
14	import SelectionPanel from "./SelectionPanel";
15	import SeoPanel from "./SeoPanel";
16	import {
17	  PREVIEW_NS,
18	  buildPreviewDocument,
19	  normalizeSelection,
20	  selectionReference,
21	  type SelectedElement,
22	  type SelectionMove,
23	} from "./preview-agent";
24	
25	type Message = { role: string; content: string };
26	type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };
27	
28	type Props = {
29	  projectId: string;
30	  projectName: string;
31	  slug: string;
32	  published: boolean;
33	  initialFiles: Record<string, string>;
34	  initialMessages: Message[];
35	  initialBalance: number;
36	  /** This user's measured average credits per build — see lib/credits.ts. */
37	  avgBuildCredits: number;
38	  /**
39	   * How many of this user's builds have actually been charged. `avgBuildCredits`
40	   * is a global fallback until this is above zero, so it is what decides whether
41	   * the pre-flight estimate may call that number "your" average.
42	   */
43	  measuredBuilds: number;
44	  /** estimateCredits() for both build kinds, resolved server-side in page.tsx. */
45	  estimates: { create: CreditRange; edit: CreditRange };
46	  /** Unread, non-spam form submissions — the badge on the Submissions link. */
47	  unreadSubmissions: number;
48	};
49	
50	const SITES_BASE = process.env.NEXT_PUBLIC_SITES_BASE ?? "kodely.site";
51	
52	// Mirrors the publish route's own Host-based derivation (see the comment
53	// there) so the header's "live site" link always matches what publish
54	// actually returned, on staging or prod, without hardcoding either.
55	const FOCUS_RING =
56	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
57	
58	// Thrown for an `error` event the SERVER sent us, so the catch below can tell
59	// "the build failed and told us why" apart from "the pipe broke" — which are
60	// completely different messages to the user. Anything else that surfaces after
61	// streaming has begun is transport, not the build.
62	class BuildServerError extends Error {}
63	
64	// The platform never changes under us, so there is nothing to subscribe to —
65	// but reading navigator during render would make the server and client
66	// disagree. useSyncExternalStore with a server snapshot is the sanctioned way
67	// to say "assume Ctrl on the server, correct it on the client", and unlike a
68	// setState-in-effect it cannot produce a hydration mismatch on the way.
69	const NO_SUBSCRIBE = () => () => {};
70	const isMacClient = () => /Mac|iPhone|iPad|iPod/.test(navigator.userAgent);
71	const isMacServer = () => false;
72	
73	function liveSiteUrl(slug: string): string {
74	  if (typeof window === "undefined") return `https://${slug}.${SITES_BASE}`;
75	  const host = window.location.host;
76	  return host.includes("staging")
77	    ? `${window.location.origin}/api/site/${slug}`
78	    : `https://${slug}.${SITES_BASE}`;
79	}
80	
81	export default function Editor(props: Props) {
82	  const [messages, setMessages] = useState<Message[]>(props.initialMessages);
83	  const [files, setFiles] = useState(props.initialFiles);
84	  const [prompt, setPrompt] = useState("");
85	  const [busy, setBusy] = useState(false);
86	  const [status, setStatus] = useState<string | null>(null);
87	  const [error, setError] = useState<string | null>(null);
88	  const [balance, setBalance] = useState(props.initialBalance);
89	  // The build just finished in THIS session, so it can be rated. Deliberately
90	  // not restored on reload: rating a build you last saw yesterday is guesswork.
91	  const [lastBuildId, setLastBuildId] = useState<string | null>(null);
92	  const [previewNonce, setPreviewNonce] = useState(0);
93	  const [published, setPublished] = useState(props.published);
94	  const [publishing, setPublishing] = useState(false);
95	  const [view, setView] = useState<"preview" | "code" | "history" | "seo" | "brand">("preview");
96	  const [builds, setBuilds] = useState<BuildCheckpoint[] | null>(null);
97	  const [restoring, setRestoring] = useState<string | null>(null);
98	  const [activeFile, setActiveFile] = useState<string | null>(null);
99	  const [downloading, setDownloading] = useState(false);
100	  const [enhancing, setEnhancing] = useState(false);
101	  // The prompt as typed, held only while an expanded spec sits in the box.
102	  // Doubles as the "we're showing a spec" flag and as what Revert restores.
103	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
104	  // A build that ended without finishing — stopped on purpose, or the stream
105	  // died. Not `error`: nothing went wrong, so it must not read like a failure.
106	  const [interruption, setInterruption] = useState<Interruption | null>(null);
107	  // Did we actually SEE the build write anything before it was interrupted?
108	  // Rendered state because BuildInterrupted's copy depends on it — see the
109	  // engine note at the top of that file for why it cannot be assumed.
110	  const [wroteFiles, setWroteFiles] = useState(false);
111	  const [device, setDevice] = useState<DeviceId>("desktop");
112	  // --- click-to-select -----------------------------------------------------
113	  // The assembled, self-contained preview document (see preview-agent.ts).
114	  const [previewDoc, setPreviewDoc] = useState<string | null>(null);
115	  const [previewLoading, setPreviewLoading] = useState(true);
116	  const [previewError, setPreviewError] = useState<string | null>(null);
117	  // Build paths index.html referenced that we could not inline. Not fatal, but
118	  // the preview is then missing something and must not pretend otherwise.
119	  const [previewMissing, setPreviewMissing] = useState<string[]>([]);
120	  // The agent inside the preview has answered. Until it has, the Select
121	  // element toggle stays disabled rather than looking live and doing nothing.
122	  const [previewReady, setPreviewReady] = useState(false);
123	  const [selectMode, setSelectMode] = useState(false);
124	  const [selection, setSelection] = useState<SelectedElement | null>(null);
125	  const frameRef = useRef<HTMLIFrameElement | null>(null);
126	  // Read inside the message listener, which is registered once — a piece of
127	  // state there would need the listener rebound on every toggle.
128	  const selectModeRef = useRef(false);
129	  const [paletteOpen, setPaletteOpen] = useState(false);
130	  // Abort has been requested but the stream hasn't unwound yet. Rendered
131	  // state, not just the ref below, so the button can actually go dead.
132	  const [stopping, setStopping] = useState(false);
133	  const streamingReply = useRef("");
134	  // Aborting this is what the Stop button does; the route's stream cancel()
135	  // sees the disconnect and aborts the model call on the server side.
136	  const abortRef = useRef<AbortController | null>(null);
137	  const stopRequested = useRef(false);
138	  const promptRef = useRef<HTMLTextAreaElement>(null);
139	  const paletteTriggerRef = useRef<HTMLButtonElement>(null);
140	  // What had focus when the palette opened, so closing can hand it back.
141	  const paletteReturn = useRef<HTMLElement | null>(null);
142	  const router = useRouter();
143	
144	  const modKey = useSyncExternalStore(NO_SUBSCRIBE, isMacClient, isMacServer) ? "⌘" : "Ctrl";
145	
146	  async function refreshFiles() {
147	    const res = await fetch(`/api/projects/${props.projectId}`);
148	    const body = await res.json();
149	    setFiles(
150	      Object.fromEntries(
151	        (body.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
152	      ),
153	    );
154	    setPreviewNonce((n) => n + 1);
155	  }
156	
157	  async function openHistory() {
158	    setView("history");
159	    const res = await fetch(`/api/projects/${props.projectId}/builds`);
160	    const body = await res.json();
161	    setBuilds(body.builds ?? []);
162	  }
163	
164	  async function restore(buildId: string) {
165	    if (!confirm("Restore this checkpoint? Your current draft will be replaced.")) return;
166	    setRestoring(buildId);
167	    setError(null);
168	    try {
169	      const res = await fetch(`/api/projects/${props.projectId}/builds/${buildId}/restore`, {
170	        method: "POST",
171	      });
172	      const body = await res.json();
173	      if (!res.ok) throw new Error(body?.error ?? "Restore failed.");
174	      const res2 = await fetch(`/api/projects/${props.projectId}`);
175	      const body2 = await res2.json();
176	      const nextFiles: Record<string, string> = Object.fromEntries(
177	        (body2.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
178	      );
179	      setFiles(nextFiles);
180	      setPreviewNonce((n) => n + 1);
181	      setView("preview");
182	    } catch (err) {
183	      setError(err instanceof Error ? err.message : "Restore failed.");
184	    } finally {
185	      setRestoring(null);
186	    }
187	  }
188	
189	  // The foundation means source files are never empty — "first build" means
190	  // no chat history yet, matching the same signal the generate route uses.
191	  const isFirstBuild = messages.length === 0;
192	
193	  // -------------------------------------------------------------------------
194	  // Assemble the preview document.
195	  //
196	  // The build output is fetched HERE, from the editor page, because this is the
197	  // only context where those requests carry the session cookie. A request made
198	  // from inside the sandboxed frame is treated as cross-site and arrives
199	  // without it — verified, and the reason the frame is fed `srcdoc` rather than
200	  // pointed at /api/preview directly. See preview-agent.ts.
201	  // -------------------------------------------------------------------------
202	  // Reset during render rather than in the effect below. A new nonce means a
203	  // new document, so the handshake, the selection and the pick mode all belong
204	  // to a page that no longer exists — and React's own guidance is to adjust
205	  // state while rendering when it derives from a changed value, not to fire an
206	  // effect and re-render a second time.
207	  const [docNonce, setDocNonce] = useState(previewNonce);
208	  if (docNonce !== previewNonce) {
209	    setDocNonce(previewNonce);
210	    setPreviewLoading(true);
211	    setPreviewError(null);
212	    setPreviewMissing([]);
213	    setPreviewReady(false);
214	    setSelection(null);
215	    setSelectMode(false);
216	  }
217	
218	  useEffect(() => {
219	    const controller = new AbortController();
220	    const base = `/api/preview/${props.projectId}`;
221	
222	    (async () => {
223	      try {
224	        const res = await fetch(`${base}/index.html`, {
225	          signal: controller.signal,
226	          cache: "no-store",
227	        });
228	        if (!res.ok) throw new Error("The preview could not be loaded. Try reloading the page.");
229	        const built = await buildPreviewDocument(await res.text(), async (path) => {
230	          const asset = await fetch(`${base}/${path}`, {
231	            signal: controller.signal,
232	            cache: "no-store",
233	          });
234	          return asset.ok ? await asset.text() : null;
235	        });
236	        if (controller.signal.aborted) return;
237	        setPreviewDoc(built.doc);
238	        setPreviewMissing(built.missing);
239	      } catch (err) {
240	        if (controller.signal.aborted) return;
241	        setPreviewError(
242	          err instanceof Error ? err.message : "The preview could not be loaded.",
243	        );
244	      } finally {
245	        if (!controller.signal.aborted) setPreviewLoading(false);
246	      }
247	    })();
248	
249	    return () => controller.abort();
250	  }, [props.projectId, previewNonce]);
251	
252	  useEffect(() => {
253	    selectModeRef.current = selectMode;
254	  }, [selectMode]);
255	
256	  // targetOrigin MUST be "*". The frame's origin is opaque, so posting to an
257	  // exact origin is silently dropped and "null" throws — both verified.
258	  function postToPreview(msg: Record<string, unknown>) {
259	    frameRef.current?.contentWindow?.postMessage({ ...msg, ns: PREVIEW_NS }, "*");
260	  }
261	
262	  useEffect(() => {
263	    function onMessage(event: MessageEvent) {
264	      // `event.origin` is the literal string "null" here, so it authenticates
265	      // nothing. Source identity is the only check worth making — and even
266	      // that only proves the message came FROM the preview, not that our agent
267	      // sent it, which is why the payload is re-validated below.
268	      const frame = frameRef.current;
269	      if (!frame || !event.source || event.source !== frame.contentWindow) return;
270	
271	      const data = event.data as Record<string, unknown> | null;
272	      if (!data || typeof data !== "object" || data.ns !== PREVIEW_NS) return;
273	
274	      if (data.type === "ready") {
275	        setPreviewReady(true);
276	        // A remount gives us a fresh document with the agent in its default
277	        // state; re-assert the mode the user had switched on.
278	        if (selectModeRef.current) postToPreview({ cmd: "set-mode", on: true });
279	        return;
280	      }
281	      if (data.type === "mode") {
282	        // The frame owns this: Escape inside the preview turns it off.
283	        setSelectMode(data.on === true);
284	        return;
285	      }
286	      if (data.type === "cleared") {
287	        setSelection(null);
288	        return;
289	      }
290	      if (data.type === "selected") {
291	        const el = normalizeSelection(data.el);
292	        if (el) setSelection(el);
293	      }
294	    }
295	
296	    // Registered once: everything it touches is a ref or a setter, so the
297	    // listener never needs rebinding.
298	    window.addEventListener("message", onMessage);
299	    return () => window.removeEventListener("message", onMessage);
300	  }, []);
301	
302	  // A fallback handshake. The agent announces itself unprompted, so this only
303	  // matters if that message raced the frame's ref being attached. It stops as
304	  // soon as the preview answers, and gives up rather than polling forever.
305	  useEffect(() => {
306	    if (!previewDoc || previewReady) return;
307	    const ping = window.setInterval(() => postToPreview({ cmd: "ping" }), 300);
308	    const giveUp = window.setTimeout(() => window.clearInterval(ping), 5000);
309	    return () => {
310	      window.clearInterval(ping);
311	      window.clearTimeout(giveUp);
312	    };
313	  }, [previewDoc, previewReady]);
314	
315	  function toggleSelectMode() {
316	    const next = !selectMode;
317	    setSelectMode(next);
318	    postToPreview({ cmd: "set-mode", on: next });
319	  }
320	
321	  function moveSelection(dir: SelectionMove) {
322	    postToPreview({ cmd: "move", dir });
323	  }
324	
325	  function clearSelection() {
326	    setSelection(null);
327	    postToPreview({ cmd: "clear" });
328	  }
329	
330	  // Puts a precise reference to the selected element at the front of the
331	  // prompt. It does NOT edit anything — the change still goes through a normal
332	  // build, and the copy in SelectionPanel says so.
333	  function insertSelectionReference() {
334	    if (!selection) return;
335	    const reference = `Change ${selectionReference(selection)}: `;
336	    setPrompt((current) => (current.startsWith(reference) ? current : reference + current));
337	    setEnhancedFrom(null);
338	    requestAnimationFrame(() => {
339	      const box = promptRef.current;
340	      if (!box) return;
341	      box.focus();
342	      box.setSelectionRange(box.value.length, box.value.length);
343	    });
344	  }
345	
346	  // If the visitor typed a prompt on the homepage before hitting the auth
347	  // wall, that prompt survives login/signup in sessionStorage — fire it
348	  // automatically the moment they land in their new project, instead of
349	  // making them retype what they already told us.
350	  useEffect(() => {
351	    if (!isFirstBuild) return;
352	    let pending: string | null = null;
353	    let pendingImage: string | null = null;
354	    try {
355	      pending = sessionStorage.getItem(PENDING_PROMPT_KEY);
356	      pendingImage = sessionStorage.getItem(PENDING_PROMPT_IMAGE_KEY);
357	    } catch {}
358	    if (!pending) return;
359	    try {
360	      sessionStorage.removeItem(PENDING_PROMPT_KEY);
361	      sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
362	    } catch {}
363	    send(pending, pendingImage ?? undefined);
364	    // Runs once on mount only — send() is intentionally not a dependency.
365	    // eslint-disable-next-line react-hooks/exhaustive-deps
366	  }, []);
367	
368	  async function send(overrideText?: string, image?: string) {
369	    const text = (overrideText ?? prompt).trim();
370	    if (!text || busy) return;
371	    if (balance <= 0) {
372	      setError("You're out of credits. Top up to keep building.");
373	      return;
374	    }
375	
376	    setBusy(true);
377	    setError(null);
378	    setInterruption(null);
379	    setWroteFiles(false);
380	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
381	    setMessages((m) => [...m, { role: "user", content: text }]);
382	    setPrompt("");
383	    setEnhancedFrom(null);
384	    streamingReply.current = "";
385	    stopRequested.current = false;
386	    const controller = new AbortController();
387	    abortRef.current = controller;
388	
389	    // Set once the first byte of the stream lands. After that point any
390	    // failure is the connection, not the request — which is what lets us tell
391	    // "couldn't start" apart from "died halfway".
392	    let streamStarted = false;
393	    // A `done` or `error` event. The route always sends one of them unless it
394	    // saw the client go away, so a stream that closes without either IS the
395	    // signature of a dropped connection.
396	    let sawTerminal = false;
397	    let touchedFiles = false;
398	
399	    try {
400	      const res = await fetch("/api/generate", {
401	        method: "POST",
402	        headers: { "Content-Type": "application/json" },
403	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
404	        signal: controller.signal,
405	      });
406	
407	      if (!res.ok || !res.body) {
408	        const body = await res.json().catch(() => ({}));
409	        throw new Error(body?.error ?? "The build failed to start.");
410	      }
411	
412	      const reader = res.body.getReader();
413	      const decoder = new TextDecoder();
414	      let buffer = "";
415	
416	      while (true) {
417	        const { done, value } = await reader.read();
418	        if (done) break;
419	        streamStarted = true;
420	        buffer += decoder.decode(value, { stream: true });
421	
422	        const parts = buffer.split("\n\n");
423	        buffer = parts.pop() ?? "";
424	
425	        for (const part of parts) {
426	          if (!part.startsWith("data: ")) continue;
427	          const event = JSON.parse(part.slice(6));
428	
429	          if (event.type === "text") {
430	            streamingReply.current += event.text;
431	          } else if (event.type === "progress" || event.type === "status") {
432	            // Both drive the same line. `progress` comes from a real tool call,
433	            // `status` from a phase the route knows about (a repair pass).
434	            setStatus(event.text);
435	          } else if (event.type === "file") {
436	            // On the SDK engine these all arrive at once after the build, so
437	            // they are a completion signal, not live progress — the progress
438	            // line above is what the user actually watches. On the `api`
439	            // engine they arrive one per write, which is what makes them
440	            // usable as evidence that a stopped build left files behind.
441	            touchedFiles = true;
442	            setWroteFiles(true);
443	          } else if (event.type === "done") {
444	            sawTerminal = true;
445	            setBalance(event.remaining);
446	            setStatus(null);
447	            setLastBuildId(event.buildId ?? null);
448	          } else if (event.type === "error") {
449	            sawTerminal = true;
450	            throw new BuildServerError(event.message);
451	          }
452	        }
453	      }
454	
455	      if (!sawTerminal) {
456	        // The pipe closed mid-build. Nothing was thrown, no error arrived —
457	        // this is exactly the silent stop the user used to be left staring at.
458	        setInterruption("connection-lost");
459	      } else if (streamingReply.current.trim()) {
460	        // Only on a build that actually completed: the route persists the
461	        // assistant reply in the success branch alone, so showing it after an
462	        // interruption would put a message on screen that a reload deletes.
463	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
464	      }
465	      // Deliberately swallowed. This runs AFTER the stream has closed cleanly,
466	      // so the build is already over and its outcome already decided — letting
467	      // a failed re-fetch fall into the catch below would report a finished
468	      // build as a lost connection, which is the one thing that block must
469	      // never say wrongly. A stale file list is a reload away; a false
470	      // "connection lost" sends the user hunting for a problem that isn't
471	      // there.
472	      if (touchedFiles) await refreshFiles().catch(() => {});
473	    } catch (err) {
474	      if (stopRequested.current) {
475	        setInterruption("stopped");
476	        // Files the agent wrote before the abort are already committed to the
477	        // draft source, so pull them in — the Code view should show what is
478	        // really there, half-finished or not.
479	        if (touchedFiles) await refreshFiles().catch(() => {});
480	      } else if (err instanceof BuildServerError) {
481	        setError(err.message);
482	      } else if (streamStarted) {
483	        setInterruption("connection-lost");
484	      } else {
485	        setError(err instanceof Error ? err.message : "Something went wrong.");
486	      }
487	    } finally {
488	      abortRef.current = null;
489	      stopRequested.current = false;
490	      setStopping(false);
491	      setBusy(false);
492	      setStatus(null);
493	    }
494	  }
495	
496	  // Stop is a real cancel, not a UI-only one: aborting the fetch closes the
497	  // response body, which fires cancel() on the route's ReadableStream, which
498	  // aborts the model request server-side. The build row is then written FAILED
499	  // with creditsCharged: 0 — nothing is billed. See BuildInterrupted.tsx.
500	  function stop() {
501	    if (!busy || stopping || !abortRef.current) return;
502	    stopRequested.current = true;
503	    setStopping(true);
504	    setStatus("Stopping…");
505	    abortRef.current.abort();
506	  }
507	
508	  // Goes through fetch rather than a plain download link so a failure lands in
509	  // the same error strip as everything else here, instead of silently saving
510	  // the JSON error body as "slug.zip".
511	  async function downloadZip() {
512	    setDownloading(true);
513	    setError(null);
514	    try {
515	      const res = await fetch(`/api/projects/${props.projectId}/export`);
516	      if (!res.ok) {
517	        const body = await res.json().catch(() => ({}));
518	        throw new Error(body?.error ?? "Download failed.");
519	      }
520	      const url = URL.createObjectURL(await res.blob());
521	      const link = document.createElement("a");
522	      link.href = url;
523	      link.download = `${props.slug}.zip`;
524	      link.click();
525	      // The click hands the blob off asynchronously, so revoking in the same
526	      // tick can cancel the download in some browsers. Next tick is enough,
527	      // and skipping the revoke entirely would pin the archive in memory for
528	      // the life of the tab.
529	      setTimeout(() => URL.revokeObjectURL(url), 0);
530	    } catch (err) {
531	      setError(err instanceof Error ? err.message : "Download failed.");
532	    } finally {
533	      setDownloading(false);
534	    }
535	  }
536	
537	  // Expand the draft prompt into a spec the user can read and edit before
538	  // spending anything. The result lands in the prompt box itself — it is
539	  // already editable, and it is already what the build button reads — so
540	  // "accept" is just pressing Build, "edit" is typing, "discard" is Revert.
541	  async function enhance() {
542	    const text = prompt.trim();
543	    if (!text || enhancing || busy) return;
544	
545	    setEnhancing(true);
546	    setError(null);
547	    try {
548	      const res = await fetch("/api/enhance", {
549	        method: "POST",
