export default function DiffView({
  diff,
  onUndo,
  undoUnavailable,
  undoing,
  onClose,
}: {
  diff: BuildDiff;
  /** Restore the previous checkpoint. Null when that is not a truthful offer. */
  onUndo: (() => void) | null;
  /** Why undo is not offered, when it is not. Shown verbatim. */
  undoUnavailable: string | null;
  undoing: boolean;
  onClose: () => void;
}) {
  const total = diff.files.reduce(
    (sum, f) => sum + f.hunks.reduce((n, h) => n + h.lines.length, 0),
    0,
  );
  const [open, setOpen] = useState<Set<string>>(
    () => new Set(total <= AUTO_EXPAND_LINES ? diff.files.map((f) => f.path) : []),
  );

  function toggle(path: string) {
    setOpen((current) => {
      const next = new Set(current);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  }

  const added = diff.files.reduce((n, f) => n + f.added, 0);
  const removed = diff.files.reduce((n, f) => n + f.removed, 0);

  return (
    <div className="h-full overflow-y-auto p-4">
      <div className="mx-auto max-w-3xl">
        <h2 className="text-sm font-medium">What this build changed</h2>
        <p className="mt-1 text-sm text-black/70 dark:text-white/70">{diff.build.prompt}</p>
        <p className="mt-1 text-xs text-black/40 dark:text-white/40">
          {new Date(diff.build.createdAt).toLocaleString()}
          {diff.previous && (
            <>
              {" · compared against the checkpoint from "}
              {new Date(diff.previous.createdAt).toLocaleString()}
            </>
          )}
        </p>

        {/* The two states where "what changed" cannot be answered as a change
            set. Both show the whole tree; only one of them is normal. */}
        {diff.previousPruned && (
          <p className="mt-3 rounded-lg border border-amber-500/40 bg-amber-500/5 px-3 py-2 text-xs text-amber-700 dark:text-amber-400">
            The earlier checkpoint&rsquo;s files have been cleared to save storage, so there is
            nothing left to compare against. Everything below is the tree as it stood after this
            build, not the change this build made.
          </p>
        )}
        {!diff.previous && !diff.previousPruned && (
          <p className="mt-3 text-xs text-black/45 dark:text-white/45">
            This is the first checkpoint of the project, so every file counts as new.
          </p>
        )}

        <p className="mt-3 text-xs text-black/50 dark:text-white/50">
          {diff.files.length === 0
            ? "No file changed."
            : `${diff.files.length} file${diff.files.length === 1 ? "" : "s"} · +${added} −${removed} lines`}
        </p>

        {/* Says plainly what this screen is and is not. The board card asked for
            approve/reject before applying; there is no before. */}
        <div className="mt-3 rounded-lg border border-black/10 px-3 py-2.5 dark:border-white/10">
          <p className="text-xs text-black/60 dark:text-white/60">
            This build has already been applied — the draft and the preview are showing it now.
            Undoing does not cancel it and does not refund its credits; it writes the previous
            checkpoint back over the draft, which you can reverse again with Redo.
          </p>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={() => onUndo?.()}
              disabled={onUndo === null || undoing}
              className={`rounded-lg border border-black/15 px-3 py-1.5 text-xs disabled:opacity-40 dark:border-white/15 ${FOCUS_RING}`}
            >
              {undoing ? "Undoing…" : "Undo this build"}
            </button>
            <button
              type="button"
              onClick={onClose}
              className={`rounded-lg border border-black/15 px-3 py-1.5 text-xs dark:border-white/15 ${FOCUS_RING}`}
            >
              Close
            </button>
            {onUndo === null && undoUnavailable && (
              <span className="text-xs text-black/45 dark:text-white/45">{undoUnavailable}</span>
            )}
          </div>
        </div>

        <ul className="mt-4 space-y-2">
          {diff.files.map((file, i) => {
            const panelId = `kodely-diff-panel-${i}`;
            const expanded = open.has(file.path);
            return (
              <li
                key={file.path}
                className="overflow-hidden rounded-lg border border-black/10 dark:border-white/10"
              >
                <button
                  type="button"
                  onClick={() => toggle(file.path)}
                  aria-expanded={expanded}
                  aria-controls={panelId}
                  disabled={file.truncated}
                  className={`flex w-full items-center justify-between gap-3 px-3 py-2 text-left disabled:cursor-default ${FOCUS_RING}`}
                >
                  <span className="flex min-w-0 items-center gap-2">
                    <span
                      aria-hidden="true"
                      className="w-3 shrink-0 text-xs text-black/35 dark:text-white/35"
                    >
                      {file.truncated ? "" : expanded ? "▾" : "▸"}
                    </span>
                    <span className="truncate font-mono text-xs">{file.path}</span>
                  </span>
                  <span className="flex shrink-0 items-center gap-2 text-xs">
                    <span className="text-black/45 dark:text-white/45">{statusLabel(file.status)}</span>
                    <span
                      className={
                        file.status === "removed"
                          ? "text-red-700 dark:text-red-400"
                          : file.status === "added"
                            ? "text-emerald-700 dark:text-emerald-400"
                            : "text-black/55 dark:text-white/55"
                      }
                    >
                      {countLabel(file)}
                    </span>
                  </span>
                </button>

                {file.approximate && (
                  <p className="border-t border-black/10 px-3 py-1.5 text-[11px] text-amber-700 dark:border-white/10 dark:text-amber-400">
                    Too much of this file changed to match it line by line, so the changed block is
                    shown as removed-then-added rather than aligned.
                  </p>
                )}
                {file.truncated && (
                  <p className="border-t border-black/10 px-3 py-1.5 text-[11px] text-black/45 dark:border-white/10 dark:text-white/45">
                    Too large to show line by line. The counts above are exact; the full file is in
                    the Code view.
                  </p>
                )}

                {expanded && !file.truncated && (
                  <div id={panelId}>
                    {file.hunks.map((hunk, h) => (
                      <HunkBlock key={h} hunk={hunk} />
                    ))}
                  </div>
                )}
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

